INSERT INTO LocalizedText (Language, Tag, Text) VALUES
('en_US', 'TXT_KEY_BUILDING_NATIVEMOUND', 'Ceremonial Mound'),
('en_US', 'TXT_KEY_BUILDING_AUL', 'Aul'),
('en_US', 'TXT_KEY_BUILDING_SACREDCAVE', 'Sacred Cave'),
('en_US', 'TXT_KEY_BUILDING_XUEMIAO', 'Kongmiao'),
('en_US', 'TXT_KEY_BUILDING_JINJA', 'Jinja'),
('en_US', 'TXT_KEY_BUILDING_GOMPA', 'Gompa'),
--
('en_US', 'TXT_KEY_BUILDING_NATIVEMOUND_STRATEGY', 'Can only be built in cities following a religion with the Ceremonial Mound belief. Construct this building by purchasing it with [ICON_PEACE] Faith. Build the Ceremonial Mound to gain Faith, Food and Gold.'),
('en_US', 'TXT_KEY_BUILDING_AUL_STRATEGY', 'Can only be built in cities following a religion with the Aul belief. Construct this building by purchasing it with [ICON_PEACE] Faith. Build the Aul to gain Faith, and Great General Points in the City.'),
('en_US', 'TXT_KEY_BUILDING_SACREDCAVE_STRATEGY', 'Can only be built in cities following a religion with the Sacred Cave belief. Construct this building by purchasing it with [ICON_PEACE] Faith. Build the Sacred Cave to gain Faith, and Tourism.'),
('en_US', 'TXT_KEY_BUILDING_XUEMIAO_STRATEGY', 'Can only be built in cities following a religion with the Kongmiao belief. Construct this building by purchasing it with [ICON_PEACE] Faith. Build the Kongmiao to gain Faith, Science, and Gold.'),
('en_US', 'TXT_KEY_BUILDING_JINJA_STRATEGY', 'Can only be built in cities following a religion with the Jinja belief. Construct this building by purchasing it with [ICON_PEACE] Faith. Build the Jinja to gain Faith, Culture and Great Admiral Points.'),
('en_US', 'TXT_KEY_BUILDING_GOMPA_STRATEGY', 'Can only be built in cities following a religion with the Gompa belief. Construct this building by purchasing it with [ICON_PEACE] Faith. Build the Gompa to gain Faith, Science, and Food.'),
--
('en_US', 'TXT_KEY_BUILDING_NATIVEMOUND_TEXT', 'In the Eastern Woodlands of North America, Indigenous cultures built monumental earthworks known as mounds, which served as important centers for social, religious, and political life. These mounds, varying in size and shape, were often constructed from layers of earth and clay, sometimes rising dozens of feet high. They could take forms such as conical burial mounds, platform mounds for ceremonial structures, or effigy mounds shaped like animals. Sites like Cahokia in present-day Illinois, Moundville in Alabama, and Poverty Point in Louisiana demonstrate the scale and sophistication of mound-building traditions, which spanned thousands of years. The construction of these mounds required organized labor and planning, reflecting the complexity and cohesion of the societies that built them. [NEWLINE][NEWLINE]The history of mound building in the Eastern United States stretches from the Archaic period (around 3500 BCE at Poverty Point) through the Woodland and Mississippian periods, peaking between 800 and 1600 CE. While the earliest mounds were primarily burial sites, later cultures used platform mounds as foundations for temples, council houses, and elite residences, symbolizing both religious authority and political power. The purpose of these structures was multifaceted: they honored the dead, served as ceremonial and ritual spaces, reinforced social hierarchies, and acted as tangible expressions of cosmology and community identity. Even after European colonization disrupted these traditions, the legacy of the mounds endures as a testament to the ingenuity, spirituality, and organizational strength of Indigenous peoples in eastern North America.'),
('en_US', 'TXT_KEY_BUILDING_AUL_TEXT', 'In Asian cultures, particularly across Central Asia, an aul refers to a traditional rural settlement or encampment that has long been associated with nomadic and semi-nomadic lifestyles. Typically consisting of yurts or later permanent houses clustered together, an aul served as both a residential and social unit for Turkic, Mongol, and Kazakh peoples, among others. Its layout reflected communal living, with families and clans gathering in close proximity to share resources, maintain herds, and hold cultural or religious rituals. Beyond its practical role as a dwelling space, the aul also carried symbolic meaning, embodying harmony with the steppe environment and the values of kinship, hospitality, and collective identity. [NEWLINE][NEWLINE]Historically, auls developed as the primary form of settlement among nomadic cultures that moved seasonally across the vast grasslands of Asia. For centuries, they facilitated mobility and adaptation to ecological cycles, supporting pastoral economies centered on horses, sheep, and cattle. With the rise of empires such as the Mongol Empire, the aul became a crucial organizational unit, enabling large-scale migration and coordination. Over time, particularly during Russian imperial expansion in the 18th–19th centuries and later Soviet rule, many auls transitioned into more permanent villages, often retaining the name but adopting fixed dwellings. Today, in countries such as Kazakhstan, Kyrgyzstan, and Mongolia, the term "aul" continues to describe small rural communities, symbolizing both a living tradition and the historical resilience of steppe cultures.'),
('en_US', 'TXT_KEY_BUILDING_SACREDCAVE_TEXT', 'Sacred caves have played an important role in many cultures worldwide, serving as natural sanctuaries for ritual, spiritual, and religious purposes. Their hidden, liminal nature—set apart from everyday life—made caves ideal places for ceremonies tied to fertility, the underworld, and divine presence. In some traditions, caves were seen as womb-like spaces symbolizing creation or rebirth, while in others they were portals to the spirit world. Archaeological evidence shows that caves were used for offerings, burials, and vision quests, often containing rock art, carvings, and altars that mark their sacred significance. [NEWLINE][NEWLINE]The history of sacred caves stretches back tens of thousands of years, from Paleolithic Europe, where early humans painted animals deep within caverns like Lascaux, to the ritual caves of Mesoamerica, where the Maya and Aztec regarded caves as entrances to the underworld (Xibalba and Mictlan). In the Mediterranean, Greek sanctuaries dedicated to gods such as Zeus and Pan were located in caves, while in South Asia, Buddhist and Hindu cave temples like Ajanta and Elephanta became monumental religious complexes. Across cultures and eras, caves consistently served as spaces where humans sought contact with the divine, underscoring their enduring role as natural places of mystery, transformation, and sacred power.'),
('en_US', 'TXT_KEY_BUILDING_XUEMIAO_TEXT', 'Kongmiao are shrines dedicated to Confucius, the ancient Chinese philosopher and teacher whose ideas shaped East Asian moral, political, and educational traditions. Architecturally, they resemble imperial palaces or classical Chinese academies, often featuring courtyards, ornate gates, stone tablets, and halls for ritual offerings. The most prominent structure within a Kongmiao is the Dacheng Hall (Hall of Great Achievement), which enshrines spirit tablets of Confucius and his notable disciples. These temples were not primarily places of worship in the sense of prayer to a deity, but rather spaces for honoring Confucius as a cultural ancestor and moral exemplar. They served as important venues for rituals, especially during annual ceremonies on Confucius’ birthday, when offerings were made to celebrate learning, virtue, and scholarly achievement. [NEWLINE][NEWLINE]The history of Kongmiao dates back to 478 BCE, when Confucius’ former home in Qufu, Shandong Province, was converted into the first temple to honor him. During the Han dynasty (206 BCE–220 CE), Confucianism was established as state ideology, and the imperial government began promoting temples to Confucius across the empire. By the Tang and Song dynasties, Kongmiao were widespread, often connected to schools and academies as centers of learning. The Ming and Qing dynasties further standardized their design and rituals, making them prominent civic and educational landmarks in nearly every county. Beyond China, Confucian temples spread to Korea, Japan, and Vietnam, where they also functioned as spaces to venerate scholars and uphold Confucian values. Today, many Kongmiao survive as cultural heritage sites, embodying the historical role of Confucianism in shaping East Asian society, governance, and education.'),
('en_US', 'TXT_KEY_BUILDING_JINJA_TEXT', 'A jinja is a Shinto shrine in Japan, serving as a sacred space where kami (divine spirits or deities) are enshrined and venerated. Typically, a jinja is marked by a torii gate at its entrance, symbolizing the transition from the ordinary world to the sacred. Within the grounds are features such as purification basins (temizuya), offering halls (haiden), and the inner sanctuary (honden), where the spirit of the kami resides. Jinja are not only places for prayer and ritual but also community centers where festivals (matsuri) are held, reinforcing local identity and seasonal cycles of nature. The architecture and layout of each shrine vary depending on its deity, region, and historical period, but all serve as points of connection between humans, nature, and the divine. [NEWLINE][NEWLINE]The history of jinja extends back to Japan’s earliest religious practices, when natural sites such as groves, mountains, and waterfalls were revered as sacred dwelling places of kami. Over time, especially during the Yayoi and Kofun periods (ca. 300 BCE–538 CE), permanent structures were built to house and honor these spirits. With the rise of the Yamato state and the codification of Shinto rituals in the Nara and Heian periods, shrines became formal institutions tied to both local communities and the imperial court. Throughout history, major shrines like Ise Jingu and Izumo Taisha gained national prominence, while countless local jinja maintained regional traditions. Even after Buddhism’s arrival and centuries of syncretism, jinja preserved their central role in Japanese spirituality. Today, they remain vital cultural and religious sites, blending ancient ritual with modern community life.'),
('en_US', 'TXT_KEY_BUILDING_GOMPA_TEXT', 'A Tibetan Gompa is a monastery or meditation hall in Tibetan Buddhism, serving as both a place of worship and a center of learning. Architecturally, Gompas often resemble fortresses or walled complexes, typically built on elevated ground, with whitewashed walls, flat roofs, and brightly painted interiors adorned with murals, thangkas (sacred paintings), and statues of Buddhas and bodhisattvas. Inside, they usually have a main assembly hall for prayer, smaller shrines, and living quarters for monks. Gompas function as hubs of spiritual practice, housing monks and nuns, preserving Buddhist scriptures, and hosting festivals, rituals, and teachings that sustain the religious life of Tibetan communities. [NEWLINE][NEWLINE]The history of Tibetan Gompas dates back to the 7th century CE, when Buddhism was first introduced to Tibet under King Songtsen Gampo. Early monasteries were influenced by Indian and Nepalese Buddhist architecture, later blended with indigenous Tibetan styles and Bon traditions. One of the earliest and most important Gompas is Samye Monastery, built in the 8th century under the guidance of Padmasambhava, who played a key role in establishing Vajrayana Buddhism in Tibet. Over time, Gompas became vital not only as spiritual centers but also as cultural and political institutions, safeguarding Tibet’s religious traditions through periods of upheaval. Today, despite challenges during the 20th century, Tibetan Gompas continue to thrive in Tibet, India, Nepal, Bhutan, and worldwide Tibetan diaspora communities.'),
--
('en_US', 'TXT_KEY_BUILDING_NATIVEMOUND_HELP', '+25% [ICON_RELIGION] Religious pressure and +10% Religious conversion resistance in this City. [NEWLINE]+1 [ICON_FOOD] Food, [ICON_GOLD] Gold from City-State Friends; +1 [ICON_FOOD] Food, [ICON_PEACE] Faith from City-State Allies.[NEWLINE][NEWLINE]-1 [ICON_HAPPINESS_3] Unhappiness from [ICON_CULTURE] Boredom.'),
('en_US', 'TXT_KEY_BUILDING_AUL_HELP', '+1 [ICON_GREAT_GENERAL] Great General Point. [NEWLINE]+25% [ICON_RELIGION] Religious pressure and +10% Religious conversion resistance in this City. [NEWLINE]+1 [ICON_FOOD] Food and [ICON_PRODUCTION] Production for every 2 Grassland or Plains tiles worked by the City.[NEWLINE][NEWLINE]-1 [ICON_HAPPINESS_3] Unhappiness from [ICON_GOLD] Poverty.'),
('en_US', 'TXT_KEY_BUILDING_SACREDCAVE_HELP', '+25% [ICON_RELIGION] Religious pressure and +10% Religious conversion resistance in this City. [NEWLINE]+1 [ICON_PEACE] Faith and [ICON_CULTURE] Culture from nearby Hills. [NEWLINE][NEWLINE]-1 [ICON_HAPPINESS_3] Unhappiness from [ICON_RELIGION] Religious Unrest.'),
('en_US', 'TXT_KEY_BUILDING_XUEMIAO_HELP', '+25% [ICON_RELIGION] Religious pressure and +10% Religious conversion resistance in this City. [NEWLINE]+1 [ICON_RESEARCH] Science from Specialists in this City. [NEWLINE]+1 [ICON_GOLD] Gold and [ICON_PEACE] Faith from Great Person improvements worked by this City. [NEWLINE][NEWLINE]1 Specialist in this City no longer produces [ICON_HAPPINESS_3] Unhappiness from [ICON_URBANIZATION] Urbanization.'),
('en_US', 'TXT_KEY_BUILDING_JINJA_HELP', '+2 [ICON_GOLDEN_AGE] Golden Age Points, +1 [ICON_GREAT_ADMIRAL] Great Admiral Point. [NEWLINE]+25% [ICON_RELIGION] Religious pressure and +10% Religious conversion resistance in this City. [NEWLINE]+1 [ICON_PEACE] Faith from Coast and Ocean tiles. +1 [ICON_PEACE] Faith and +2 [ICON_CULTURE] Culture from Atolls and Sea Resources worked by this City.[NEWLINE][NEWLINE]-1 [ICON_HAPPINESS_3] Unhappiness from [ICON_RESEARCH] Illiteracy.'),
('en_US', 'TXT_KEY_BUILDING_GOMPA_HELP', '+25% [ICON_RELIGION] Religious pressure and +10% Religious conversion resistance in this City. [NEWLINE]City gains +1 [ICON_FOOD] Food and [ICON_PEACE] Faith for every Mountain within 3 tiles of the City. [NEWLINE]Receive 5 [ICON_RESEARCH] Science whenever you unlock a Policy, scaling with Era.'),
