CREATE TRIGGER IF NOT EXISTS JarKongmiao AFTER INSERT ON Improvements
WHEN NEW.CreatedByGreatPerson = 1
BEGIN
	INSERT INTO Building_ImprovementYieldChanges
			(BuildingType, 		ImprovementType, YieldType, Yield)
	SELECT	'BUILDING_XUEMIAO', NEW.Type,	'YIELD_FAITH',1	UNION ALL
	SELECT	'BUILDING_XUEMIAO', NEW.Type,	'YIELD_GOLD', 1;
END;

